eval@path:(async () => {
  const F = window.__tmtFluids;
  const s = window.__tmtGame.snapshot;
  const t = s.tanks[s.active].position;
  const r0 = Math.hypot(...t);
  const u = t.map(v => v / r0);
  const a = Math.abs(u[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
  const c1 = [u[1] * a[2] - u[2] * a[1], u[2] * a[0] - u[0] * a[2], u[0] * a[1] - u[1] * a[0]];
  const l1 = Math.hypot(...c1);
  const e1 = c1.map(v => v / l1);
  const e2 = [u[1] * e1[2] - u[2] * e1[1], u[2] * e1[0] - u[0] * e1[2], u[0] * e1[1] - u[1] * e1[0]];
  const at = (x, y) => { const d = [0, 1, 2].map(k => u[k] + (e1[k] * x + e2[k] * y) / r0); const l = Math.hypot(...d); return d.map(v => v / l * r0); };
  let seed = 7;
  const rand = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
  for (let round = 0; round < 6; round++) {
    const cand = [];
    for (let i = 0; i < 64; i++) { const q = rand() * Math.PI * 2, d = 2 + rand() * 24; cand.push([Math.cos(q) * d, Math.sin(q) * d]); }
    const res = await F.probe(cand.map(([x, y]) => at(x, y)));
    for (let i = 0; i < res.length; i++) {
      if (res[i].water < 0.25 || res[i].water > 1.4) continue;
      const [cx, cy] = cand[i];
      for (let k = 0; k < 8; k++) {
        const q = k / 8 * Math.PI;
        const dx = Math.cos(q), dy = Math.sin(q);
        const line = [];
        for (let j = -2; j <= 2; j++) line.push([cx + dx * j, cy + dy * j]);
        const w = await F.probe(line.map(([x, y]) => at(x, y)));
        if (w.every(z => z.water > 0.1)) {
          const level = res[i].surface;
          const lift = (p, h) => { const r = Math.hypot(...p); return p.map(v => v / r * (level + h)); };
          window.__path = { from: lift(at(cx - dx * 3, cy - dy * 3), 0.1), to: lift(at(cx + dx * 3, cy + dy * 3), 0.1), mid: lift(at(cx, cy), 0), level };
          return JSON.stringify({ centre: [cx, cy].map(v => +v.toFixed(2)), dir: k, level: +level.toFixed(3), depths: w.map(z => +z.water.toFixed(2)) });
        }
      }
    }
  }
  return 'no path';
})()

